import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { watchInputs } from "./watch-inputs.ts";

// Types read straight from supabase/schemas, with no database: the permissions the core checks,
// the audit actions it writes, and the values a text column's `check (column in (...))` allows.
// `supabase gen types` types those as plain strings; this keeps the TypeScript lists from drifting.

export const SCHEMA_TYPES_PATH = join("packages", "db", "src", "types", "schema.gen.ts");

const HEADER =
  "// Generated by `bogey types` from supabase/schemas. Do not edit manually.\n" +
  "// `bogey watch --schema` keeps it up to date.\n\n";

const DOTTED = /^[a-z][a-z0-9_-]*\.[a-z][a-z0-9_-]*$/;

export interface SchemaTypes {
  permissions: string[];
  auditActions: string[];
  columnValues: Map<string, Map<string, string[]>>;
  problems: string[];
}

function withoutComments(sql: string): string {
  return sql.replace(/(^|\s)--[^\n]*/g, "$1");
}

function literals(text: string): string[] {
  return [...text.matchAll(/'([^']*)'/g)].map((match) => match[1]!);
}

/** Each call of `fn` in `sql`, as its top-level arguments. */
export function callsOf(sql: string, fn: string): string[][] {
  const calls: string[][] = [];
  const opener = `${fn}(`;
  let at = sql.indexOf(opener);
  while (at !== -1) {
    const args: string[] = [];
    let depth = 0;
    let quoted = false;
    let start = at + opener.length;
    let i = start;
    for (; i < sql.length; i++) {
      const char = sql[i];
      if (char === "'") quoted = !quoted;
      if (quoted) continue;
      if (char === "(") depth++;
      else if (char === ")") {
        if (depth === 0) break;
        depth--;
      } else if (char === "," && depth === 0) {
        args.push(sql.slice(start, i).trim());
        start = i + 1;
      }
    }
    args.push(sql.slice(start, i).trim());
    calls.push(args);
    at = sql.indexOf(opener, i);
  }
  return calls;
}

function enums(sql: string): Map<string, string[]> {
  const found = new Map<string, string[]>();
  for (const match of sql.matchAll(/create type public\.(\w+) as enum \(([^)]*)\)/g)) {
    found.set(match[1]!, literals(match[2]!));
  }
  return found;
}

export function readSchemaTypes(sources: Tuple<{ file: string; sql: string }>): SchemaTypes {
  const problems: string[] = [];
  const permissions = new Set<string>();
  const auditActions = new Set<string>();
  const columnValues = new Map<string, Map<string, string[]>>();
  const all = withoutComments(sources.map((source) => source.sql).join("\n"));
  const types = enums(all);

  for (const { file, sql: raw } of sources) {
    const sql = withoutComments(raw);

    for (const fn of ["private.has_permission", "private.holds_permission", "private.tags_grant"]) {
      for (const args of callsOf(sql, fn)) {
        const permission = literals(args.at(-1) ?? "")[0];
        if (permission && DOTTED.test(permission)) permissions.add(permission);
      }
    }
    for (const block of sql.matchAll(/insert into public\.role_permissions[^;]*;/g)) {
      for (const [, , permission] of block[0].matchAll(/\('([^']+)',\s*'([^']+)'\)/g)) {
        if (permission && DOTTED.test(permission)) permissions.add(permission);
      }
    }

    for (const fn of ["private.audit", "private.audit_org"]) {
      for (const args of callsOf(sql, fn)) {
        const action = args[1] ?? "";
        // `'registration.' || new.status::text` stands for every value of registration_status
        const dynamic = /^'([a-z_]+)\.'\s*\|\|\s*(?:\w+\.)?(\w+)::text$/.exec(action);
        if (dynamic) {
          const [, prefix, column] = dynamic;
          const values = types.get(`${prefix}_${column}`);
          if (!values) {
            problems.push(
              `${file}: ${action} needs an enum named ${prefix}_${column} to list its actions`,
            );
            continue;
          }
          for (const value of values) auditActions.add(`${prefix}.${value}`);
          continue;
        }
        for (const name of literals(action)) if (DOTTED.test(name)) auditActions.add(name);
      }
    }

    for (const table of sql.matchAll(/create table public\.(\w+) \(([\s\S]*?)\n\);/g)) {
      for (const check of table[2]!.matchAll(/check \((\w+) in \(([^)]*)\)\)/g)) {
        const columns = columnValues.get(table[1]!) ?? new Map<string, string[]>();
        columns.set(check[1]!, literals(check[2]!));
        columnValues.set(table[1]!, columns);
      }
    }
  }

  return {
    permissions: [...permissions].sort(),
    auditActions: [...auditActions].sort(),
    columnValues: new Map(
      [...columnValues]
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([table, columns]) => [
          table,
          new Map([...columns].sort(([a], [b]) => a.localeCompare(b))),
        ]),
    ),
    problems,
  };
}

function list(values: Tuple<string>, indent: string): string {
  return `[\n${values.map((value) => `${indent}  ${JSON.stringify(value)},\n`).join("")}${indent}]`;
}

export function schemaTypesModule(types: SchemaTypes): string {
  const tables = [...types.columnValues]
    .map(([table, columns]) => {
      const entries = [...columns]
        .map(
          ([column, values]) =>
            `    ${column}: [${values.map((value) => JSON.stringify(value)).join(", ")}],\n`,
        )
        .join("");
      return `  ${table}: {\n${entries}  },\n`;
    })
    .join("");
  return (
    HEADER +
    "/** Every permission the core schema checks or grants; plugins add `<plugin>.<name>` ones. */\n" +
    `export const CORE_PERMISSIONS = ${list(types.permissions, "")} as const;\n\n` +
    "export type CorePermission = (typeof CORE_PERMISSIONS)[number];\n\n" +
    "/** Every action the core schema writes to the audit log. */\n" +
    `export const CORE_AUDIT_ACTIONS = ${list(types.auditActions, "")} as const;\n\n` +
    "export type CoreAuditAction = (typeof CORE_AUDIT_ACTIONS)[number];\n\n" +
    "/** What each text column with a `check (column in (...))` allows, by table and column. */\n" +
    `export const COLUMN_VALUES = {\n${tables}} as const;\n\n` +
    "export type CheckedTable = keyof typeof COLUMN_VALUES;\n\n" +
    "/** One value `table.column`'s check allows. */\n" +
    "export type ColumnValue<\n" +
    "  T extends CheckedTable,\n" +
    "  C extends keyof (typeof COLUMN_VALUES)[T],\n" +
    "> = (typeof COLUMN_VALUES)[T][C] extends ReadonlyArray<infer V> ? V : never;\n"
  );
}

function readSources(root: string): { file: string; sql: string }[] {
  const dir = join(root, "supabase", "schemas");
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .filter((file) => file.endsWith(".sql"))
    .sort()
    .map((file) => ({ file, sql: readFileSync(join(dir, file), "utf-8") }));
}

/** Writes packages/db/src/types/schema.gen.ts, or with `check`, only says whether it's current. */
export function generateSchemaTypes(
  root: string,
  check = false,
): { ok: boolean; changed: boolean; output: string } {
  const types = readSchemaTypes(readSources(root));
  if (types.problems.length) {
    return {
      ok: false,
      changed: false,
      output: `✗ schema types:\n  ${types.problems.join("\n  ")}`,
    };
  }
  const path = join(root, SCHEMA_TYPES_PATH);
  const content = schemaTypesModule(types);
  const current = existsSync(path) ? readFileSync(path, "utf-8") : "";
  if (current === content) {
    return { ok: true, changed: false, output: `✓ ${SCHEMA_TYPES_PATH} is up to date` };
  }
  if (check) {
    return {
      ok: false,
      changed: false,
      output: `✗ ${SCHEMA_TYPES_PATH} is stale: run \`bogey types --schema\``,
    };
  }
  writeFileSync(path, content);
  return { ok: true, changed: true, output: `✓ wrote ${SCHEMA_TYPES_PATH}` };
}

export function watchSchemaTypes(root: string, log: (line: string) => void): () => void {
  return watchInputs(root, ["supabase/schemas"], () => {
    const result = generateSchemaTypes(root);
    if (result.changed || !result.ok) log(result.output);
  });
}
